{"path": "transpose.py", "content": "def transpose(text):
    rows = text.split("\n")
    # Pad each row on the right to the longest row at or below it, so that
    # shorter rows get left-padded in the output but nothing is right-padded.
    padded = []
    longest = 0
    for row in reversed(rows):
        longest = max(longest, len(row))
        padded.append(row.ljust(longest))
    padded.reverse()

    width = len(padded[0]) if padded else 0
    return "\n".join(
        "".join(row[col] for row in padded if col < len(row))
        for col in range(width)
    )
"}
